#nullable enable // autogenerated  

using MVZ2.Vanilla.Entities;
using PVZEngine;
using PVZEngine.Damages;
using PVZEngine.Definitions;
using PVZEngine.Entities;

namespace MVZ2.GameContent.Enemies
{
    [AutoEntityBehaviourDefinition(VanillaEnemyNames.Mannequin)]
    public class Mannequin : BoatedEnemyBehaviour
    {
        public Mannequin(string nsp, string name) : base(nsp, name)
        {
        }

        public override void Init(Entity entity)
        {
            base.Init(entity);
            HealthLossSpawnHelper.Init(entity, ID);
        }

        protected override void UpdateLogic(Entity entity)
        {
            base.UpdateLogic(entity);
            // 每损失 100 血，基于图鉴进度放置一个器械，最多 2 次  
            HealthLossSpawnHelper.CheckHealthLossTrigger(entity, ID, 100f, 2,
                e => HealthLossSpawnHelper.SpawnFromAlmanac(e));
        }

        public override void PostDeath(Entity entity, DeathInfo info)
        {
            base.PostDeath(entity, info);
            if (entity.WillRemoveOnDeath(info))
                return;
            entity.SpawnWithParams(VanillaEnemyID.MannequinTNT, entity.Position);
        }

        private static readonly NamespaceID ID = VanillaEnemyID.Mannequin;
    }
}
